import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  date,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";

/**
 * Schema conventions:
 * - ids: uuid, generated by Postgres
 * - money: bigint minor units (paise), JS number mode — never floats
 *   sign convention: negative = outflow (expense), positive = inflow (income)
 * - timestamps: timestamptz, created_at/updated_at on every table
 * - soft delete / archive: *_at nullable timestamptz
 */

export const users = pgTable("users", {
  id: uuid("id").primaryKey().defaultRandom(),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  displayName: text("display_name").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

/** Per-user assumptions used only for forward-looking goal projections. */
export const projectionSettings = pgTable("projection_settings", {
  userId: uuid("user_id")
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  /** Broad-equity annual return assumption (1200 = 12%). */
  equityReturnBps: integer("equity_return_bps").notNull().default(1200),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * `custom` is a generic OpenAI-compatible endpoint (base URL + key + model);
 * the others are named providers with fixed base URLs (see packages/ai/factory).
 */
export const aiProvider = pgEnum("ai_provider", [
  "none",
  "anthropic",
  "ollama",
  "openrouter",
  "deepseek",
  "custom",
]);

/**
 * Per-user AI provider config. Replaces the old global AI_* env vars: the API's
 * AI features and the email extractor both resolve the provider from here. The
 * API key is encrypted at rest with the same secret-box envelope as mailbox
 * secrets (keyed by MAILBOX_SECRET), so the extractor can decrypt it too.
 */
export const aiSettings = pgTable("ai_settings", {
  userId: uuid("user_id")
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  provider: aiProvider("provider").notNull().default("none"),
  /** encrypted API key; "" for ollama/none */
  apiKeyEnc: text("api_key_enc").notNull().default(""),
  /** base URL for ollama/custom; "" otherwise */
  baseUrl: text("base_url").notNull().default(""),
  /** model name; provider default used when "" */
  model: text("model").notNull().default(""),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * `ppf`, `epf` and `ssy` are accounts rather than holdings because their balance
 * is known exactly — interest is credited at a fixed rate, not estimated. NPS
 * and gold move with a daily NAV/price, so they stay holdings, where a valuation
 * carries the as-of date that makes the estimate honest.
 */
export const accountType = pgEnum("account_type", [
  "bank",
  "cash",
  "credit_card",
  "investment",
  "loan",
  // Generic overdraft/line-of-credit account. It shares drawing-power details
  // with an overdraft home loan but is kept distinct for reporting and labels.
  "overdraft",
  "ppf",
  "epf",
  // Sukanya Samriddhi: a PPF twin (fixed govt rate, credited annually, matures
  // ~21 years out, has an account number). Reuses the scheme-details structure.
  "ssy",
  // Overdraft home loan (SBI Maxgain and its equivalents). A distinct type, not
  // just a loan: you park surplus into it to cut interest and can withdraw it
  // back, so it carries a sanctioned limit and a drawing power a term loan has
  // no notion of. The balance is still what you owe (net of parked surplus), so
  // it lands in the loans bucket like any liability.
  "home_loan_od",
  // DEPRECATED: insurance is now a standalone entity (see insurance_policies),
  // not an account. This enum value is retained only because Postgres cannot drop
  // an enum value; no account uses it and the UI no longer offers it.
  "insurance",
]);

export const accounts = pgTable(
  "accounts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id),
    /** human-facing label, e.g. "HDFC Joint" — never parsed; display comes from this alone */
    name: text("name").notNull(),
    type: accountType("type").notNull(),
    /** issuing bank/institution; a lookup key for import matching, not a display badge */
    institution: text("institution"),
    /**
     * Last 4 digits, shown in lists so two HDFC accounts are tellable apart.
     * Derived from bank_details.account_number whenever one exists — see
     * syncAccountLast4 — so the two can never disagree. Set by hand only when
     * the full number isn't recorded.
     */
    accountLast4: text("account_last4"),
    /**
     * Whose account this is. Universal, not bank-only: a card has a name on it
     * and a PPF has a holder. Without this the holder gets packed into `name`
     * ("HDFC Ammu PPF"), which is the same trap the last-4 used to be in.
     */
    holderName: text("holder_name"),
    /**
     * UPI handles that resolve to this account, primary first. Not bank-only —
     * RuPay credit cards link to UPI too, so this can't live on bank_details.
     */
    upiIds: text("upi_ids")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    currency: text("currency").notNull().default("INR"),
    openingBalancePaise: bigint("opening_balance_paise", { mode: "number" })
      .notNull()
      .default(0),
    /**
     * Goal this account is earmarked for; net worth and goal funding group by
     * it. Null = the "Unassigned" bucket. Set-null on goal delete so the account
     * survives. A goal's funded value is the sum of the assets that point here.
     */
    // AnyPgColumn keeps inference stable across the accounts → goals reference
    // (goals is declared after accounts in this file).
    goalId: uuid("goal_id").references((): AnyPgColumn => goals.id, { onDelete: "set null" }),
    sortOrder: integer("sort_order").notNull().default(0),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("accounts_user_idx").on(t.userId)],
);

export const categoryKind = pgEnum("category_kind", ["income", "expense"]);

export const categories = pgTable(
  "categories",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id),
    name: text("name").notNull(),
    kind: categoryKind("kind").notNull(),
    parentId: uuid("parent_id"),
    icon: text("icon").notNull().default(""),
    color: text("color").notNull().default(""),
    sortOrder: integer("sort_order").notNull().default(0),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("categories_user_idx").on(t.userId),
    uniqueIndex("categories_user_name_parent_idx").on(t.userId, t.name, t.parentId),
  ],
);

export const transactionSource = pgEnum("transaction_source", ["manual", "import", "recurring"]);

export const transactions = pgTable(
  "transactions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id),
    date: date("date").notNull(),
    amountPaise: bigint("amount_paise", { mode: "number" }).notNull(),
    merchant: text("merchant").notNull().default(""),
    categoryId: uuid("category_id").references(() => categories.id),
    notes: text("notes").notNull().default(""),
    tags: text("tags")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    source: transactionSource("source").notNull().default("manual"),
    /**
     * Insurance policy this expense pays a premium for — a link to an
     * insurance_policies row, kept apart from `accountId` (the account the money
     * left). Null for ordinary transactions. Lets a policy show its premium
     * history without being an account itself. See services/insurance.ts.
     */
    policyId: uuid("policy_id").references((): AnyPgColumn => insurancePolicies.id, {
      onDelete: "set null",
    }),
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("transactions_user_date_idx").on(t.userId, t.date.desc(), t.id.desc()),
    index("transactions_account_idx").on(t.accountId),
    index("transactions_category_idx").on(t.categoryId),
    index("transactions_policy_idx").on(t.policyId),
  ],
);

export const transactionSplits = pgTable(
  "transaction_splits",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    transactionId: uuid("transaction_id")
      .notNull()
      .references(() => transactions.id, { onDelete: "cascade" }),
    categoryId: uuid("category_id")
      .notNull()
      .references(() => categories.id),
    amountPaise: bigint("amount_paise", { mode: "number" }).notNull(),
    note: text("note").notNull().default(""),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("transaction_splits_tx_idx").on(t.transactionId)],
);

export const transferLinks = pgTable(
  "transfer_links",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id),
    outTransactionId: uuid("out_transaction_id")
      .notNull()
      .unique()
      .references(() => transactions.id, { onDelete: "cascade" }),
    inTransactionId: uuid("in_transaction_id")
      .notNull()
      .unique()
      .references(() => transactions.id, { onDelete: "cascade" }),
    auto: boolean("auto").notNull().default(false),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("transfer_links_user_idx").on(t.userId)],
);

